struct Ring: ProgressViewStyle {
    func makeBody(configuration: Configuration) -> some View {
        Circle()
            .trim(from: 0, to: configuration.fractionCompleted ?? 0)
            .stroke(.tint, lineWidth: 6)
            .rotationEffect(.degrees(-90))
    }
}

